verdict = None
skip_at = min(
    (m.start() for p in _SKIP_PATTERNS if (m := re.search(p, lowered))), default=None
)
apply_at = min(
    (m.start() for p in _APPLY_PATTERNS if (m := re.search(p, lowered))), default=None
)
if skip_at is not None:
    verdict = "SKIP"
elif apply_at is not None:
    verdict = "APPLY"

if verdict is None:
    raise ParseError("no verdict found in baseline output")

# A label counts as claimed only if the model wrote it. Underscores are
# optional because models reformat ids into prose.
