for blocker_id in known_types:
    pattern = re.escape(blocker_id).replace(r"\_", r"[\s_-]")
    if re.search(rf"\b{pattern}\b", lowered):
        named.append(Claim(blocker_id, ""))

return Prediction(verdict=verdict, blockers=named)

